import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"收缩层次 CH","description":"","frontmatter":{"title":"收缩层次 CH","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/contraction-hierarchies.md","filePath":"cs/contraction-hierarchies.md","lastUpdated":1789023840000}'),p={name:"cs/contraction-hierarchies.md"};function u(_,a,A,m,C,E){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="收缩层次-ch" tabindex="-1">收缩层次 CH <a class="header-anchor" href="#收缩层次-ch" aria-label="Permalink to &quot;收缩层次 CH&quot;">​</a></h1><div class="epigraph"><p>按重要性收缩顶点，用捷径补上被删点的最短路角色；查询只向上走，路网规模上比朴素 Dijkstra 快几个数量级。</p><footer>—— 据 Geisberger, Sanders, Schultes and Delling, Contraction Hierarchies, 2008 整理</footer></div><p>上一课<a href="/cs/bidirectional-alt">双向与 ALT</a>用路标造 \\(h\\)。收缩层次（CH）把预处理做成<strong>改图</strong>：删点加捷边。不重写三角启发。缺口是收缩顺序与查询的向上搜索。本课路网静态；动态边权下一课换连通性结构，不是 CH 更新全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>给顶点重要性（度、捷边数、层级启发式）。收缩 \\(v\\)：对 \\(v\\) 的邻对 \\((u,w)\\)，若 \\(u\\)–\\(v\\)–\\(w\\) 是唯一或必要最短，加捷边 \\(u\\to w\\) 权 \\(d(u,v)+d(v,w)\\)（见证搜索判断是否已有不经 \\(v\\) 的更短路）。查询：从 \\(s\\) 与 \\(t\\) 只走向层级更高的邻接（含捷边），双向直到稳定。最短路在「先升后降」的层级上。</p><p>缺口是捷边维护最短路，不是 A* 的 \\(f\\)。</p><h3 id="顺序是启发不是定理" tabindex="-1">顺序是启发不是定理 <a class="header-anchor" href="#顺序是启发不是定理" aria-label="Permalink to &quot;顺序是启发不是定理&quot;">​</a></h3><p>差顺序导致捷边爆炸。实践用局部重要性排队。正确性：任意顺序只要捷边补全「经被删点的最短」，查询图仍保留最短路。空间与时间是工程。</p><p><span class="marginnote">Geisberger 等 2008。后续 Customizable CH、PHAST 全源。本课直觉：收缩 + 向上。后课动态连通性是边插删，不是路网权更新的 CH 维护。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：按序收缩，见证 Dijkstra 决定捷边。在线：双向只走更高层。还原路径时展开捷边为原路径。</p>',11)),(e(),n(h,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E6%94%B6%E7%BC%A9%E9%A1%BA%E5%BA%8F%22%5D%20--%3E%20SH%5B%22%E5%88%A0%E7%82%B9%E5%8A%A0%E6%8D%B7%E8%BE%B9%22%5D%0A%20%20SH%20--%3E%20UP%5B%22%E6%9F%A5%E8%AF%A2%E5%8F%AA%E5%90%91%E4%B8%8A%22%5D%0A%20%20UP%20--%3E%20SP%5B%22%E6%9C%80%E7%9F%AD%E8%B7%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 ALT 可叠加，本课单独 CH 已够。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>低层点被收缩后，高层仍通过捷边「看见」它们的中转。查询向上：类似最高点当 LCA 式的交会。与 Kruskal 重构树：都是预处理树/层，但 CH 针对最短路而非瓶颈。与 Dijkstra：查询图边少、方向受限。</p><p>不要在任意稠密图上期望 CH 奇迹：路网低度和层次结构是前提。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写时间窗、不写并行定制化 CH 细节。不进导航产品。后课默认：静态路网最短路预处理首选 CH 一类。下一课动态连通：边插删下维护连通。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>收缩补捷边，查询只向高层。</li><li>顺序启发决定空间；正确性靠捷边语义。</li><li>适合稀疏有层次的路网。</li><li>出处：Geisberger, Sanders, Schultes and Delling, 2008。</li></ul>',8))])}const H=o(p,[["render",u]]);export{b as __pageData,H as default};
